/**
 * Audit D — axe-core a11y suite for FluxyChat dashboard.
 *
 * Runs against the 5 onboarding steps + 2 core pages and asserts zero
 * Critical/Serious WCAG violations. Moderate/Minor are logged but not
 * blocking (they're speculative without real user testing).
 *
 * Auth: mirrors the smoke spec pattern. We do NOT require Clerk auth —
 * the test uses the `fc_console_ack=1` cookie to bypass the
 * "first-time acknowledgement" gate, which lets the page render
 * unauthenticated. For pages that redirect to /sign-in without
 * Clerk, the test is skipped at runtime.
 */
import { test, expect } from "@playwright/test";
import AxeBuilder from "@axe-core/playwright";

const ONBOARDING_STEPS = [
  { name: "step-1-welcome", path: "/onboarding?step=1" },
  { name: "step-2-project", path: "/onboarding?step=2" },
  { name: "step-3-keys", path: "/onboarding?step=3" },
  { name: "step-4-rooms", path: "/onboarding?step=4" },
  { name: "step-5-done", path: "/onboarding?step=5" },
];

const CORE_PAGES = [
  { name: "landing", path: "/" },
  { name: "status", path: "/status" },
];

async function attachConsoleAckCookie(context: import("@playwright/test").BrowserContext) {
  await context.addCookies([
    {
      name: "fc_console_ack",
      value: "1",
      url: "http://127.0.0.1:3000",
    },
  ]);
}

test.describe("axe a11y — onboarding", () => {
  for (const step of ONBOARDING_STEPS) {
    test(`${step.name} has no Critical or Serious violations`, async ({ page, context }) => {
      await attachConsoleAckCookie(context);
      const response = await page.goto(step.path, { waitUntil: "domcontentloaded" });
      if (!response || response.status() >= 400) {
        test.skip(true, `page returned ${response?.status() ?? "no response"} — page not reachable in smoke mode`);
      }
      const results = await new AxeBuilder({ page }).analyze();
      // Log every violation (Moderate/Minor included) so the report
      // surfaces the full picture, not just the blocking ones.
      for (const v of results.violations) {
        const nodeCount = v.nodes.length;
        const firstNode = v.nodes[0]?.target?.join(" ") ?? "(no selector)";
        const html = v.nodes[0]?.html?.slice(0, 200) ?? "(no html)";
        console.log(
          `[a11y] ${v.impact ?? "unknown"} ${v.id}: ${v.help} (${nodeCount} node(s); first: ${firstNode}) html=${html}`,
        );
      }
      const criticalOrSerious = results.violations.filter(
        (v) => v.impact === "critical" || v.impact === "serious",
      );
      expect(criticalOrSerious).toHaveLength(0);
    });
  }
});

test.describe("axe a11y — core pages", () => {
  for (const p of CORE_PAGES) {
    test(`${p.name} has no Critical or Serious violations`, async ({ page, context }) => {
      await attachConsoleAckCookie(context);
      const response = await page.goto(p.path, { waitUntil: "domcontentloaded" });
      if (!response || response.status() >= 400) {
        test.skip(true, `page returned ${response?.status() ?? "no response"} — page not reachable in smoke mode`);
      }
      const results = await new AxeBuilder({ page }).analyze();
      for (const v of results.violations) {
        const nodeCount = v.nodes.length;
        const firstNode = v.nodes[0]?.target?.join(" ") ?? "(no selector)";
        console.log(
          `[a11y] ${v.impact ?? "unknown"} ${v.id}: ${v.help} (${nodeCount} node(s); first: ${firstNode})`,
        );
      }
      const criticalOrSerious = results.violations.filter(
        (v) => v.impact === "critical" || v.impact === "serious",
      );
      expect(criticalOrSerious).toHaveLength(0);
    });
  }
});
